/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen1Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Ensure output is predictable
        mapper.configure(SerializationFeature.INDENT_OUTPUT, false);
        tokenBuffer = new TokenBuffer(mapper);
    }





    /**
     * Tests complex nesting to ensure context depth management works correctly.
     */
    @Test
    public void testWriteEndArray_ComplexNesting() throws IOException {
        tokenBuffer.writeStartObject();       // Level 1
        tokenBuffer.writeStartArray();        // Level 2
        tokenBuffer.writeStartObject();       // Level 3
        tokenBuffer.writeEndObject();         // Back to Level 2
        tokenBuffer.writeEndArray();          // Back to Level 1
        tokenBuffer.writeEndObject();         // Back to Root

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        assertEquals(JsonToken.NOT_AVAILABLE, parser.nextToken());
    }


}

